import copy
import math


class ParcelLedger:
    def __init__(self):
        self._records = {}

    @staticmethod
    def _validate(record):
        if not isinstance(record, dict):
            raise TypeError("record must be a dictionary")
        if set(record) != {"parcel_id", "mass", "position", "labels"}:
            raise ValueError("record has invalid fields")
        if not isinstance(record["parcel_id"], str):
            raise TypeError("parcel_id must be a string")
        if not record["parcel_id"]:
            raise ValueError("parcel_id must not be empty")
        if isinstance(record["mass"], bool) or not isinstance(record["mass"], int):
            raise TypeError("mass must be an integer")
        if record["mass"] < 0:
            raise ValueError("mass must be non-negative")
        position = record["position"]
        if not isinstance(position, dict):
            raise TypeError("position must be a dictionary")
        if set(position) != {"x", "y"}:
            raise ValueError("position has invalid fields")
        for value in position.values():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("coordinates must be numeric")
            if not math.isfinite(value):
                raise ValueError("coordinates must be finite")
        labels = record["labels"]
        if not isinstance(labels, list):
            raise TypeError("labels must be a list")
        if not all(isinstance(label, str) for label in labels):
            raise TypeError("labels must contain strings")

    def put(self, record):
        self._validate(record)
        self._records[record["parcel_id"]] = record.copy()

    def get(self, parcel_id):
        if not isinstance(parcel_id, str):
            raise TypeError("parcel_id must be a string")
        record = self._records.get(parcel_id)
        return copy.deepcopy(record) if record is not None else None

    def all_records(self):
        return [copy.deepcopy(self._records[key]) for key in sorted(self._records)]

